mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rnum, a.* FROM ( SELECT r.review_post_id AS reviewPostId, r.user_id AS userId, u.nickname AS nickname, r.review_board_title AS reviewBoardTitle, r.review_board_content AS reviewBoardContent, r.review_board_count AS reviewBoardCount, r.review_board_scrap_count AS reviewBoardScrapCount, r.review_board_report_status AS reviewBoardReportStatus, r.review_board_report_count AS reviewBoardReportCount, NVL(l.like_count, 0) AS likeCount, NVL(c.comment_count, 0) AS commentCount, TO_CHAR(r.review_board_regdate, 'YYYY-MM-DD HH24:MI:SS') AS reviewBoardRegdate FROM tblReviewBoard r JOIN tblUser u ON r.user_id = u.user_id LEFT JOIN ( SELECT review_post_id, COUNT(*) AS like_count FROM tblReviewLike GROUP BY review_post_id ) l ON r.review_post_id = l.review_post_id LEFT JOIN ( SELECT review_post_id, COUNT(*) AS comment_count FROM tblReviewComment WHERE review_comment_status = 'A' GROUP BY review_post_id ) c ON r.review_post_id = c.review_post_id
AND ( LOWER(r.review_board_title) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(r.review_board_content) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(u.nickname) LIKE '%' || LOWER(#{keyword}) || '%' )
ORDER BY r.review_board_regdate DESC ) a WHERE ROWNUM <= #{end, jdbcType=NUMERIC} ) WHERE rnum >= #{start, jdbcType=NUMERIC}

mapper.update:
UPDATE tblReviewBoard
SET review_board_count = review_board_count + 1
WHERE review_post_id = #{reviewPostId}

mapper.select:
